import { test } from "node:test";
import assert from "node:assert/strict";
import { loadConfig } from "../src/config.mjs";
import { run } from "../src/run.mjs";
import { emit } from "../src/log.mjs";

test("verbose defaults to false", () => {
  assert.equal(loadConfig({ name: "a" }).verbose, false);
  assert.equal(loadConfig().verbose, false);
});

test("verbose is preserved when supplied", () => {
  assert.equal(loadConfig({ name: "a", verbose: true }).verbose, true);
});

test("emit honours the verbose flag", () => {
  assert.equal(emit("hi", { verbose: false }), "hi");
  assert.equal(emit("hi", { verbose: true }), "[verbose] hi");
});

test("run threads the flag end to end", () => {
  assert.equal(run({ name: "svc" }), "svc");
  assert.equal(run({ name: "svc", verbose: true }), "[verbose] svc");
});
